{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The policy attached to the user allows '*' actions on IAM resources, potentially granting full IAM privileges."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc3-passrole-user-attach-policy" {
  user       = aws_iam_user.fn1-privesc3-partial-user.name
  policy_arn = aws_iam_policy.fn1-passrole-star-constrained.arn
}

resource "aws_iam_policy" "fn1-passrole-star-constrained" {
  name        = "fn1-passrole-star-constrained"
  description = "Constrained version of fn1-passrole-star"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "*"
      }
    ]
  })
}",
  "fix_summary": "Replaced the overly permissive policy 'fn1-passrole-star' with a new constrained policy 'fn1-passrole-star-constrained' that still allows 'iam:PassRole' on all resources but does not grant full IAM privileges."
}
